={{ JSON.stringify((() => {
  const obj = {
    parent: { database_id: $json.deal.notion.id },
    properties: Object.fromEntries(
      Object.entries($json.deal.properties)
        .filter(([_, entry]) => entry.value !== "" && entry.value !== "\"\"" && entry.value !== null && entry.value !== undefined)
        .map(([key, entry]) => [
          key,
          entry.type === "title"
            ? { title: [{ text: { content: entry.value } }] }
            : entry.type === "rich_text" || entry.type === "text"
            ? { rich_text: [{ text: { content: entry.value } }] }
            : entry.type === "multi_select"
            ? { multi_select: Array.isArray(entry.value) ? entry.value.map(option => ({ name: option.trim() })) : entry.value.split(",").map(option => ({ name: option.trim() })) }
            : entry.type === "select"
            ? { select: { name: entry.value } }
            : entry.type === "url"
            ? { url: entry.value }
            : entry.type === "number"
            ? { number: Number(entry.value) }
            : entry.type === "email"
            ? { email: entry.value }
            : null
        ])
        .filter(([_, value]) => value !== null)
    )
  };

  // Recursive function to remove empty fields, including empty objects and nested empty objects
  const removeEmptyFields = (obj) => {
    if (Array.isArray(obj)) {
      const filteredArray = obj.map(removeEmptyFields).filter(item => item !== null && item !== "" && item !== "\"\"");
      return filteredArray.length > 0 ? filteredArray : null;
    } else if (typeof obj === "object" && obj !== null) {
      const filteredObject = Object.fromEntries(
        Object.entries(obj)
          .map(([key, value]) => [key, removeEmptyFields(value)])
          .filter(([_, value]) => 
            value !== null && 
            value !== "" && 
            value !== "\"\"" && 
            !(typeof value === "object" && Object.keys(value).length === 0) // Removes empty objects!
          )
      );

      // If the object is empty after filtering, return null (removes parent field)
      return Object.keys(filteredObject).length > 0 ? filteredObject : null;
    }
    return obj;
  };

  // Ensure the whole object is removed if it becomes empty
  return removeEmptyFields(obj) || null;
})());
}}
